if((int)$db->query('SELECT COUNT(*) FROM coupons')->fetchColumn()===0){$q=$db->prepare('INSERT INTO coupons(code,discount_percent,discount_amount,min_purchase) VALUES(?,?,?,?)');foreach([['WELCOME20',20,0,50000],['CASHBACK12',0,12000,100000],['FEST2COST',10,0,75000]] as $x)$q->execute($x);}

$_SESSION['cart']??=[];
function rupiah(int $n):string{return 'Rp '.number_format($n,0,',','.');}
function e(string $s):string{return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
function out(array $x):never{header('Content-Type: application/json');echo json_encode($x);exit;}
function token():string{$_SESSION['csrf']??=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function verify():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??''))out(['ok'=>false,'message'=>'Sesi keamanan berakhir. Muat ulang halaman.']);}
function auth():bool{return isset($_SESSION['user_id']);}
function need():void{if(!auth()){header('Location:?page=login');exit;}}
function cartRows(PDO $db):array{$rows=[];$sub=0;foreach($_SESSION['cart'] as $id=>$qty){$q=$db->prepare('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1');$q->execute([(int)$id]);$p=$q->fetch(PDO::FETCH_ASSOC);if($p){$p['qty']=(int)$qty;$p['line']=$p['price']*$qty;$sub+=$p['line'];$rows[]=$p;}}return [$rows,$sub];}

$page=$_GET['page']??'dashboard';$action=$_POST['action']??'';
if($action==='login'){$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$q=$db->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_email']=$u['email'];$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location:?page=dashboard');exit;}$loginError='Email atau password salah.';}
