if($action==='update_account'){
 verify();
 $uid=(int)$_SESSION['user_id'];
 $current=$_POST['current_password']??'';
 $email=strtolower(trim($_POST['email']??''));
 $new=$_POST['new_password']??'';
 $confirm=$_POST['confirm_password']??'';
 $q=$db->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$q->execute([$uid]);$u=$q->fetch(PDO::FETCH_ASSOC);
 if(!$u||!password_verify($current,$u['password_hash'])) out(['ok'=>false,'message'=>'Password saat ini salah.']);
 if(!filter_var($email,FILTER_VALIDATE_EMAIL)) out(['ok'=>false,'message'=>'Format email baru tidak valid.']);
 $q=$db->prepare('SELECT id FROM users WHERE email=? AND id<>? LIMIT 1');$q->execute([$email,$uid]);
 if($q->fetchColumn()) out(['ok'=>false,'message'=>'Email tersebut sudah digunakan.']);
 if($new!=='' && strlen($new)<8) out(['ok'=>false,'message'=>'Password baru minimal 8 karakter.']);
 if($new!==$confirm) out(['ok'=>false,'message'=>'Konfirmasi password baru tidak sama.']);
 if($new!==''){$q=$db->prepare('UPDATE users SET email=?,password_hash=? WHERE id=?');$q->execute([$email,password_hash($new,PASSWORD_DEFAULT),$uid]);}
 else {$q=$db->prepare('UPDATE users SET email=? WHERE id=?');$q->execute([$email,$uid]);}
 session_regenerate_id(true);$_SESSION['user_email']=$email;$_SESSION['csrf']=bin2hex(random_bytes(32));
 out(['ok'=>true,'message'=>'Akun berhasil diperbarui.']);
}
if($action==='save_product'){
 verify();
 $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $cat=(int)($_POST['category_id']??0); $price=(int)preg_replace('/\D+/','', (string)($_POST['price']??0)); $stock=(int)preg_replace('/\D+/','', (string)($_POST['stock']??0)); $desc=trim($_POST['description']??'');
 $q=$db->prepare('SELECT image FROM products WHERE id=?'); $q->execute([$id]); $oldImage=$q->fetchColumn() ?: '';
 $image=$oldImage ?: trim($_POST['image']??'🍰');
 if($name===''||$cat<1)out(['ok'=>false,'message'=>'Nama kue dan kategori wajib diisi.']);
 if($price<=0)out(['ok'=>false,'message'=>'Harga kue harus lebih dari Rp 0.']);
 if($stock<0)out(['ok'=>false,'message'=>'Stok tidak boleh negatif.']);
 if(isset($_FILES['image_file']) && $_FILES['image_file']['error']!==UPLOAD_ERR_NO_FILE){
   $f=$_FILES['image_file'];
   if($f['error']!==UPLOAD_ERR_OK) out(['ok'=>false,'message'=>'Upload gambar gagal.']);
   if($f['size']>12*1024*1024) out(['ok'=>false,'message'=>'Ukuran gambar maksimal 12 MB.']);
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);
   $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];
   if(!isset($allowed[$mime])) out(['ok'=>false,'message'=>'Format gambar harus JPG, PNG, WEBP, atau GIF.']);
   $filename='cake_'.date('YmdHis').'_'.bin2hex(random_bytes(4)).'.'.$allowed[$mime];
   if(!is_dir($uploadDir) && !mkdir($uploadDir,0775,true)) out(['ok'=>false,'message'=>'Folder upload tidak dapat dibuat.']);
   if(!move_uploaded_file($f['tmp_name'],$uploadDir.'/'.$filename)) out(['ok'=>false,'message'=>'Gambar tidak dapat disimpan. Periksa izin folder uploads/products.']);
   if($oldImage && str_starts_with($oldImage,'uploads/products/') && is_file(__DIR__.'/'.$oldImage)) @unlink(__DIR__.'/'.$oldImage);
   $image='uploads/products/'.$filename;
 }
 if($id){$q=$db->prepare('UPDATE products SET name=?,category_id=?,price=?,stock=?,description=?,image=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([$name,$cat,$price,$stock,$desc,$image,$id]);}
 else{$q=$db->prepare('INSERT INTO products(name,category_id,price,stock,description,image) VALUES(?,?,?,?,?,?)');$q->execute([$name,$cat,$price,$stock,$desc,$image]);}
 out(['ok'=>true,'message'=>'Kue berhasil disimpan.']);
}
if($action==='archive_product'){verify();$id=(int)($_POST['id']??0);$q=$db->prepare('UPDATE products SET is_active=0,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([$id]);out(['ok'=>true,'message'=>'Kue dinonaktifkan. Histori tetap aman.']);}
if($action==='cart_add'){verify();$id=(int)$_POST['id'];$qty=max(1,(int)($_POST['qty']??1));$q=$db->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$q->execute([$id]);$stock=(int)$q->fetchColumn();if($stock<1)out(['ok'=>false,'message'=>'Stok habis.']);$_SESSION['cart'][$id]=min($stock,($_SESSION['cart'][$id]??0)+$qty);out(['ok'=>true]);}
if($action==='cart_set'){verify();$id=(int)$_POST['id'];$qty=max(0,(int)$_POST['qty']);$q=$db->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$q->execute([$id]);$stock=(int)$q->fetchColumn();if($qty===0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($stock,$qty);out(['ok'=>true]);}
