if($action==='save_financial_entry'){
 verify();
 $type=$_POST['type']??'income'; $category=trim($_POST['category']??'Lainnya'); $description=trim($_POST['description']??'');
 $amount=(int)preg_replace('/\D+/','',(string)($_POST['amount']??0));
 if(!in_array($type,['income','expense'],true)) out(['ok'=>false,'message'=>'Jenis transaksi tidak valid.']);
 if($description==='') out(['ok'=>false,'message'=>'Nama transaksi wajib diisi.']);
 if($amount<=0) out(['ok'=>false,'message'=>'Nominal harus lebih dari Rp 0.']);
 $photo='';
 if(isset($_FILES['photo']) && $_FILES['photo']['error']!==UPLOAD_ERR_NO_FILE){
   $f=$_FILES['photo'];
   if($f['error']!==UPLOAD_ERR_OK) out(['ok'=>false,'message'=>'Upload foto transaksi gagal.']);
   if($f['size']>8*1024*1024) out(['ok'=>false,'message'=>'Ukuran foto maksimal 8 MB.']);
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);
   $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
   if(!isset($allowed[$mime])) out(['ok'=>false,'message'=>'Foto harus JPG, PNG, atau WEBP.']);
   $filename='cash_'.date('YmdHis').'_'.bin2hex(random_bytes(4)).'.'.$allowed[$mime];
   if(!move_uploaded_file($f['tmp_name'],$financeUploadDir.'/'.$filename)) out(['ok'=>false,'message'=>'Foto transaksi tidak dapat disimpan.']);
   $photo='uploads/finance/'.$filename;
 }
 $q=$db->prepare('INSERT INTO financial_entries(entry_date,type,category,description,amount,reference,photo) VALUES(?,?,?,?,?,?,?)');
 $q->execute([date('Y-m-d H:i:s'),$type,$category,$description,$amount,trim($_POST['reference']??'')?:null,$photo?:null]);
 out(['ok'=>true,'message'=>'Transaksi kas berhasil disimpan.']);
}
if($action==='checkout'){
 verify(); [$items,$subtotal]=cartRows($db); if(!$items)out(['ok'=>false,'message'=>'Keranjang masih kosong.']);
 $name=trim($_POST['name']??'Pelanggan'); $phone=trim($_POST['phone']??''); $payment=$_POST['payment']??'Cash'; $cash=max(0,(int)($_POST['cash']??0)); $coupon=strtoupper(trim($_POST['coupon']??'')); $notes=trim($_POST['notes']??'');
 if($name==='')$name='Pelanggan';
 $allowedPayments=['Cash','QRIS','Transfer','NonTunai','Komplimen','Deposit']; if(!in_array($payment,$allowedPayments,true))out(['ok'=>false,'message'=>'Metode pembayaran tidak valid.']);
 $discount=0; if($coupon){$q=$db->prepare('SELECT * FROM coupons WHERE code=? AND active=1');$q->execute([$coupon]);$c=$q->fetch(PDO::FETCH_ASSOC);if($c&&$subtotal>=(int)$c['min_purchase'])$discount=$c['discount_amount']?(int)$c['discount_amount']:(int)round($subtotal*$c['discount_percent']/100);}
 $total=max(0,$subtotal-$discount); $change=0; $breakdown=trim($_POST['payment_breakdown']??''); $cashForOrder=$cash;
 if($breakdown!==''){
   $parts=[]; foreach(explode('|',$breakdown) as $part){$z=explode(':',$part,2); if(count($z)===2){$m=trim($z[0]);$v=(int)$z[1];if($v>0)$parts[]=$m.':'.$v;}}
   $sum=array_sum(array_map(fn($x)=>(int)explode(':',$x,2)[1],$parts)); if($sum!==$total)out(['ok'=>false,'message'=>'Total pembayaran pisah harus sama dengan total tagihan.']);
   $cashForOrder=0; foreach($parts as $part){$z=explode(':',$part,2);if(strcasecmp(trim($z[0]),'Cash')===0)$cashForOrder+=(int)$z[1];}
   $breakdown=implode('|',$parts); $payment='Split';
 } elseif($payment==='Cash') { if($cash<$total)out(['ok'=>false,'message'=>'Uang diterima masih kurang '.rupiah($total-$cash)]); $change=$cash-$total; }
 $ref=$payment==='Cash'?'CASH-'.strtoupper(bin2hex(random_bytes(4))):strtoupper($payment).'-'.strtoupper(bin2hex(random_bytes(5)));
 try{
   $db->beginTransaction(); $q=$db->prepare('INSERT INTO customers(name,phone) VALUES(?,?)');$q->execute([$name,$phone]);$customer=$db->lastInsertId();$invoice='LC-'.date('Ymd-His').'-'.random_int(100,999);
   $q=$db->prepare('INSERT INTO orders(invoice,customer_id,order_date,subtotal,discount,total,payment_method,payment_status,order_status,cash_received,change_amount,coupon_code,payment_reference,notes,payment_breakdown) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
   $q->execute([$invoice,$customer,date('Y-m-d H:i:s'),$subtotal,$discount,$total,$payment,'PAID','COMPLETED',$cashForOrder,$change,$coupon?:null,$ref,$notes?:null,$breakdown?:null]); $oid=(int)$db->lastInsertId();
   $it=$db->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,qty,subtotal) VALUES(?,?,?,?,?,?)');$up=$db->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=? AND is_active=1');
   foreach($items as $p){$up->execute([$p['qty'],$p['id'],$p['qty']]);if($up->rowCount()!==1)throw new RuntimeException('Stok berubah.');$it->execute([$oid,$p['id'],$p['name'],$p['price'],$p['qty'],$p['line']]);}
   $fin=$db->prepare("INSERT INTO financial_entries(entry_date,type,category,description,amount,order_id,reference) VALUES(?,?,?,?,?,?,?)");$fin->execute([date('Y-m-d H:i:s'),'income','Penjualan','Penjualan '.$invoice,$total,$oid,$ref]);
   $db->commit(); $_SESSION['cart']=[]; out(['ok'=>true,'invoice'=>$invoice,'total'=>$total,'change'=>$change,'reference'=>$ref]);
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();out(['ok'=>false,'message'=>'Transaksi dibatalkan. Stok dan laporan tidak berubah.']);}
}

