_format((int)$db->query("SELECT COUNT(*) FROM orders WHERE date(order_date)=date('now','localtime')")->fetchColumn())?></b></div></div><div class="panel"><h2 style="margin-top:0">Daftar Pesanan</h2><p style="color:#8a7b70;font-size:13px">Semua transaksi yang berhasil dibayar tersimpan otomatis di sini.</p><div class="table"><table><tr><th>Invoice</th><th>Tanggal</th><th>Pelanggan</th><th>Total</th><th>Metode Pembayaran</th><th>Status</th></tr><?php if(!$orders):?><tr><td colspan="6" class="empty">Belum ada pesanan.</td></tr><?php else: foreach($orders as $o):?><tr><td class="invoice"><?=e($o['invoice'])?></td><td><?=e($o['order_date'])?></td><td><?=e($o['customer']??'Pelanggan')?></td><td><b><?=rupiah((int)$o['total'])?></b></td><td><?=e($o['payment_method'])?></td><td><span class="badge"><?=e($o['order_status']??'COMPLETED')?></span></td></tr><?php endforeach; endif;?></table></div></div></div></body></html><?php exit;}
