<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kas Kasir — LUSH.CAKE</title><style>:root{--brand:#98500f;--brand2:#c1732b;--bg:#f7f4f1;--line:#eadfd6;--text:#2b211b;--muted:#8a7b70;--soft:#fff0e4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,sans-serif}.wrap{max-width:1250px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}.logo{font-size:25px;font-weight:950;letter-spacing:3px;color:var(--brand)}.sub{color:var(--muted);font-size:13px}.back,.primary{background:var(--brand);color:#fff;text-decoration:none;padding:11px 16px;border-radius:11px;border:0;font-weight:800;cursor:pointer;box-shadow:0 5px 14px #98500f22}.back:hover,.primary:hover{background:#7f420c}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.card{background:#fff;border:1px solid var(--line);border-radius:17px;padding:17px;box-shadow:0 4px 18px #2b211b0a}.card small{color:var(--muted)}.card b{display:block;font-size:21px;margin-top:7px}.income{border-top:4px solid var(--brand2)}.expense{border-top:4px solid #a33b31}.balance{border-top:4px solid var(--brand)}.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 5px 18px #2b211b08}.panelhead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}.table{overflow:auto;-webkit-overflow-scrolling:touch}.table table{width:100%;min-width:760px;border-collapse:collapse;font-size:13px}.table th,.table td{padding:12px;border-bottom:1px solid #f0e9e3;text-align:left;white-space:nowrap}.table th{color:#6f6259;background:#fffaf7}.in{color:#159b70;font-weight:800}.out{color:#a33b31;font-weight:800}.photo{width:38px;height:38px;object-fit:cover;border-radius:8px;border:1px solid var(--line)}.modal{position:fixed;inset:0;background:#2b211b99;display:none;place-items:center;padding:15px;z-index:20}.modal.show{display:grid}.box{background:#fff;border-radius:20px;width:min(720px,100%);max-height:92vh;overflow:auto;padding:20px;box-shadow:0 20px 60px #2b211b33}.close{float:right;border:0;background:none;font-size:25px;cursor:pointer;color:var(--text)}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:12px;border:1px solid var(--line);border-radius:10px;font:inherit;background:#fff;color:var(--text)}.field input:focus,.field select:focus,.field textarea:focus{outline:2px solid #98500f33;border-color:var(--brand)}.field textarea{min-height:90px;resize:vertical}.full{grid-column:1/-1}.hint{font-size:11px;color:var(--muted);margin-top:5px}@media(max-width:900px){.wrap{padding:18px}.cards{grid-template-columns:repeat(2,1fr)}.top{align-items:flex-start}.panelhead{align-items:flex-start;flex-wrap:wrap}}@media(max-width:600px){.wrap{padding:12px}.cards{grid-template-columns:1fr}.top{flex-direction:column}.top>div:last-child{display:flex;width:100%;gap:8px}.top>div:last-child>*{flex:1;text-align:center}.panel{padding:14px}.panelhead{flex-direction:column;align-items:stretch}.panelhead .primary{width:100%}.box{padding:16px;border-radius:16px;max-height:96vh}.formgrid{grid-template-columns:1fr}.full{grid-column:auto}.table table{min-width:700px}.card b{font-size:20px}}@media(max-width:380px){.wrap{padding:10px}.logo{font-size:21px}.sub{font-size:12px}.back,.primary{padding:10px 12px;font-size:13px}}</style></head><body><div class="wrap"><div class="top"><div><div class="logo">LUSH.CAKE</div><div class="sub">Kasir · Kas Kasir · Pencatatan uang masuk dan keluar</div></div><div style="display:flex;gap:8px"><button class="primary" onclick="cashModal()">＋ Transaksi</button><a class="back" href="?page=dashboard">← Kasir</a></div></div><div class="cards"><div class="card income"><small>Pemasukan</small><b><?=rupiah($cashIncome)?></b></div><div class="card expense"><small>Pengeluaran</small><b><?=rupiah($cashExpense)?></b></div><div class="card balance"><small>Saldo Kas</small><b><?=rupiah($cashIncome-$cashExpense)?></b></div><div class="card"><small>Kas Hari Ini</small><b><?=rupiah($cashToday)?></b></div></div><div class="panel"><div class="panelhead"><div><h2 style="margin:0">Kas Kasir</h2><div class="sub">Penjualan otomatis masuk sebagai pemasukan. Pengeluaran/modal dapat dicatat manual.</div></div><button class="primary" onclick="cashModal()">＋ Tambah Transaksi Kas</button></div><div class="table"><table><tr><th>Foto</th><th>Tanggal</th><th>Jenis Transaksi</th><th>Kategori</th><th>Nama</th><th>Jumlah</th><th>Referensi</th></tr><?php if(!$cashRows):?><tr><td colspan="7" style="text-align:center;padding:45px;color:#71808b">Belum ada transaksi kas.</td></tr><?php else:foreach($cashRows as $r):?><tr><td><?php if($r['photo']):?><img class="photo" src="<?=e($r['photo'])?>" alt="Foto transaksi"><?php else:?>—<?php endif;?></td><td><?=e($r['entry_date'])?></td><td class="<?=$r['type']==='income'?'in':'out'?>"><?=$r['type']==='income'?'Uang Masuk':'Uang Keluar'?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td><b><?=rupiah((int)$r['amount'])?></b></td><td><?=e($r['reference']??'-')?></td></tr><?php endforeach;endif;?></table></div></div></div><div class="modal" id="cashModal"><div class="box"><button class="close" onclick="closeCash()">×</button><h2 style="margin-top:0">Tambah Transaksi Kas Kasir</h2><form id="cashForm" enctype="multipart/form-data"><div class="formgrid"><div class="field full"><label>Jenis Transaksi</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><label style="border:1px solid #d8e4eb;border-radius:10px;padding:12px"><input type="radio" name="type" value="income" checked> Uang Masuk</label><label style="border:1px solid #d8e4eb;border-radius:10px;padding:12px"><input type="radio" name="type" value="expense"> Uang Keluar</label></div></div><div class="field full"><label>Nama Transaksi</label><input name="description" maxlength="150" placeholder="Contoh: Modal Awal / Belanja bahan / Setoran" required></div><div class="field"><label>Nominal</label><input name="amount" id="cashAmount" inputmode="numeric" placeholder="100.000" required></div><div class="field"><label>Kategori</label><select name="category"><option>Modal Awal</option><option>Penjualan</option><option>Pembelian Bahan</option><option>Operasional</option><option>Gaji</option><option>Setoran</option><option>Penjualan Deposit</option><option>Lainnya</option></select></div><div class="field"><label>Referensi</label><input name="reference" placeholder="Opsional"></div><div class="field"><label>Unggah Foto</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><div class="hint">Struk/bukti transaksi, maksimal 8 MB.</div></div><div class="field full"><label>Catatan</label><textarea name="notes" placeholder="Catatan tambahan (opsional)"></textarea></div><button class="primary full" type="submit">Simpan</button></div></form></div></div><script>const CSRF=<?=json_encode(token())?>;const cm=document.getElementById('cashModal');const formatIDRInput=n=>{const digits=String(n??'').replace(/\D/g,'');return digits?Number(digits).toLocaleString('id-ID'):''};const numericInput=n=>Number(String(n??'').replace(/\D/g,''))||0;function bindMoneyInput(el){if(!el)return;el.addEventListener('input',()=>{const pos=el.selectionStart;const before=String(el.value).slice(0,pos).replace(/\D/g,'').length;el.value=formatIDRInput(el.value);let count=0,newPos=el.value.length;for(let i=0;i<el.value.length;i++){if(/\d/.test(el.value[i]))count++;if(count>=before){newPos=i+1;break}}try{el.setSelectionRange(newPos,newPos)}catch(e){}})}function cashModal(){cm.classList.add('show');document.getElementById('cashAmount').focus()}function closeCash(){cm.classList.remove('show')}function cashReq(form){const d=new FormData(form);d.append('action','save_financial_entry');d.append('csrf',CSRF);return fetch(location.href,{method:'POST',body:d}).then(r=>r.json())}const cashAmount=document.getElementById('cashAmount');bindMoneyInput(cashAmount);document.getElementById('cashForm').addEventListener('submit',e=>{e.preventDefault();const a=document.getElementById('cashAmount');a.value=String(numericInput(a.value));cashReq(e.target).then(x=>{if(x.ok){alert(x.message);location.reload()}else alert(x.message)}).catch(()=>alert('Koneksi gagal.'))});cm.addEventListener('click',e=>{if(e.target===cm)closeCash()});</script></body></html><?php exit;}
