otal{border-top:1px solid var(--line);padding-top:10px;font-size:17px;font-weight:950;color:var(--text)}.wide{width:100%;margin-top:8px}.manage{margin-top:18px}.table{overflow:auto}.table table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{padding:9px;border-bottom:1px solid #f0e9e3;text-align:left}.actions{display:flex;gap:5px}.badge{padding:4px 7px;border-radius:99px;background:#eaf7ed;color:#28743c;font-size:10px}.modal{display:none;position:fixed;inset:0;background:#1e140d66;z-index:20;align-items:center;justify-content:center;padding:15px}.modal.show{display:flex}.modalbox{width:min(650px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:20px;padding:22px}.modalhead{display:flex;justify-content:space-between;align-items:center}.x{border:0;border-radius:50%;width:33px;height:33px;cursor:pointer}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field{margin:8px 0}.field label{display:block;font-size:12px;font-weight:850;margin-bottom:5px}.field input,.field textarea,.field select{width:100%;padding:10px;border:1px solid var(--line);border-radius:10px}.field textarea{min-height:75px}.full{grid-column:1/-1}.payrow{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.pay{padding:11px;border:1px solid var(--line);border-radius:10px;background:#fff;cursor:pointer}.pay.active{background:#fff0e4;border-color:var(--brand);color:var(--brand);font-weight:900}.quick{display:flex;flex-wrap:wrap;gap:6px} .quick .btn{width:auto!important;min-width:110px}#cash{position:relative;z-index:30;pointer-events:auto!important;cursor:text!important;background:#fff!important;font-size:18px;font-weight:800;letter-spacing:.3px}.secure{background:#f1f8f2;color:#2c6e3a;padding:10px;border-radius:10px;font-size:11px}.coupon{display:flex;gap:7px}.coupon input{flex:1}.flash{position:fixed;right:20px;bottom:20px;background:#2b211b;color:#fff;padding:12px 15px;border-radius:12px;display:none;z-index:50}.flash.show{display:block}.empty{padding:25px;text-align:center;color:var(--muted)}
