.thumb img{width:100%;height:100%;object-fit:contain;object-position:center;display:block;background:#fff}.uploadPreview{display:none;margin-top:10px;border:1px solid var(--line);border-radius:14px;background:#faf7f4;min-height:180px;max-height:340px;padding:12px;align-items:center;justify-content:center;overflow:hidden}.uploadPreview.show{display:flex}.uploadPreview img{display:block;max-width:100%;max-height:310px;width:auto;height:auto;object-fit:contain;object-position:center;border-radius:10px}.uploadMeta{margin-top:7px;font-size:11px;color:var(--muted)}.product{overflow:hidden}.filehint{font-size:12px;color:#8a7b70}.btn:disabled{opacity:.5;cursor:not-allowed}.actions .btn{width:auto;padding:9px 12px}.toast{position:fixed;right:20px;bottom:20px;z-index:99;background:#2b211b;color:#fff;padding:13px 17px;border-radius:12px;box-shadow:0 10px 30px #0002}.paymentResult{margin-top:8px;padding:10px 12px;border-radius:10px;background:#f8f4ef;color:#6f6259;font-weight:800;font-size:13px}.paymentResult.kembali{background:#eaf7ed;color:#28743c}.paymentResult.kurang{background:#fff0ef;color:#a33b31}.paytotal{display:flex;justify-content:space-between;align-items:center;background:#fff8f2;border:1px solid #eadfd6;padding:13px;border-radius:12px}.paytotal b{font-size:20px;color:var(--brand)}</style></head><body><div class="app"><aside class="side"><div class="logo">LUSH.CAKE</div><nav class="nav"><a class="<?=($page==='dashboard' ? 'active' : '')?>" href="?page=dashboard"><span>Kasir</span></a><a href="#produk"><span>Produk</span></a><a class="<?=($page==='orders' ? 'active' : '')?>" href="?page=orders"><span>Pesanan</span></a><a class="<?=($page==='cash' ? 'active' : '')?>" href="?page=cash"><span>Kas Kasir</span></a><a class="<?=($page==='reports' ? 'active' : '')?>" href="?page=reports"><span>Laporan Keuangan</span></a><a href="?logout=1"><span>Keluar</span></a></nav></aside><main class="main">
<div class="top"><form class="search"><input name="q" value="<?=e($search)?>" placeholder="Cari cake, cupcake, bakery..." onchange="this.form.submit()"></form><div class="user">👤 <b><?=e($_SESSION['user_name'])?></b><button class="btn secondary accountBtn" onclick="accountModal()">Akun</button><a class="logout" href="?logout=1">Keluar</a></div></div>
<div class="hero"><div><h1>Kasir LUSH.CAKE</h1><p>Checkout cepat, stok otomatis, dan pencatatan keuangan tanpa kerja manual.</p></div></div>
<div class="stats"><div class="stat"><small>Pesanan</small><b><?=number_format((int)$stats['orders'])?></b></div><div class="stat"><small>Omzet</small><b><?=rupiah((int)$stats['omzet'])?></b></div><div class="stat"><small>Omzet Hari Ini</small><b><?=rupiah($today)?></b></div><div class="stat"><small>Stok Menipis</small><b><?=$low?> produk</b></div></div>
<div class="grid"><section id="produk"><div class="chips"><a class="chip <?=$cat===0?'active':''?>" href="?">Semua</a><?php foreach($cats as $c):?><a class="chip <?=$cat===$c['id']?'active':''?>" href="?cat=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="head"><h2>Produk LUSH.CAKE</h2><button class="btn primary" onclick="productModal()">＋ Tambah Kue</button></div><div class="products"><?php foreach($products as $p):?><article class="product"><div class="pic"><?php if(str_starts_with((string)$p['image'],'uploads/products/')):?><img src="<?=e($p['image'])?>" alt="<?=e($p['name'])?>"><?php else:?><?=e($p['image']?:'🍰')?><?php endif;?></div><div class="pname"><?=e($p['name'])?></div><div class="meta"><?=e($p['category'])?> · Stok <?=$p['stock']?></div><div class="price"><?=rupiah((int)$p['price'])?></div><button class="btn add" onclick="add(<?=$p['id']?>)" <?=$p['stock']<1?'disabled':''?>>＋ Tambah ke Kasir</button></article><?php endforeach;?></div>
<div class="panel manage"><div class="head"><h2>Kelola Kue</h2><span class="notice">Histori transaksi tetap aman</span></div><div class="table"><table><tr><th>Kue</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr><?php foreach($products as $p):?><tr><td><b><?=e($p['name'])?></b><br><span class="notice"><?=e($p['category'])?></span></td><td><?=rupiah((int)$p['price'])?></td><td><?=$p['stock']?></td><td class="actions"><button class="btn secondary" onclick='productModal(<?=json_encode($p)?>)'>Edit</button><button class="btn danger" onclick="archive(<?=$p['id']?>)">Nonaktifkan</button></td></tr><?php endforeach;?></table></div></div>
</section>
<aside class="cart"><h2>Keranjang <span class="notice">(<?=array_sum($_SESSION['cart'])?> item)</span></h2><?php if(!$cart):?><div class="empty">Keranjang kosong.<br>Pilih kue untuk mulai.</div><?php else:foreach($cart as $p):?><div class="cartitem"><div class="thumb"><?php if(str_starts_with((string)$p['image'],'uploads/products/')):?><img src="<?=e($p['image'])?>" alt=""><?php else:?><?=e($p['image']?:'🍰')?><?php endif;?></div><div class="ci"><b><?=e($p['name'])?></b><small><?=rupiah((int)$p['price'])?></small><div class="qty"><button onclick="setCart(<?=$p['id']?>,<?=$p['qty']-1?>)">−</button><b><?=$p['qty']?></b><button onclick="setCart(<?=$p['id']?>,<?=$p['qty']+1?>)">＋</button></div></div><b><?=rupiah((int)$p['line'])?></b></div><?php endforeach;endif;?><div class="row"><span>Subtotal</span><b><?=rupiah($subtotal)?></b></div><div class="row total"><span>Total</span><b><?=rupiah($subtotal)?></b></div><button class="btn primary wide" onclick="checkout()" <?=$cart?'':'disabled'?>>Bayar Sekarang</button><button class="btn secondary wide" onclick="clearCart()" <?=$cart?'':'disabled'?>>Kosongkan</button></aside></div></main></div><div class="modal" id="modal"><div class="modalbox" id="modalbox"></div></div><div class="flash" id="flash"></div>
<script>const CSRF=<?=json_encode(token())?>,M=document.getElementById('modal'),B=document.getElementById('modalbox');function req(d){const isForm=d instanceof FormData;if(isForm){if(!d.has('csrf'))d.append('csrf',CSRF)}else{d.csrf=CSRF}return fetch(location.href,{method:'POST',headers:isForm?{}:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:isForm?d:new URLSearchParams(d)}).then(async r=>{const t=await r.text();try{return JSON.parse(t)}catch(e){console.error(t);return {ok:false,message:'Server error ('+r.status+'). '+t.slice(0,300)}}}).catch(e=>({ok:false,message:'Koneksi gagal. Pastikan server PHP masih berjalan.'}))}function go(x){if(x.ok)location.reload();else alert(x.message)}function add(id){req({action:'cart_add',id}).then(go)}function setCart(id,qty){req({action:'cart_set',id,qty}).then(go)}function clearCart(){if(confirm('Kosongkan keranjang?'))req({action:'cart_clear'}).then(go)}function closeM(){M.classList.remove('show')}function esc(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}function accountModal(){M.classList.add('show');B.innerHTML=`<div class="modalhead"><h2>Pengaturan Akun</h2><button class="x" onclick="closeM()">×</button></div><p class="notice">Ganti email dan/atau password akun kasir. Password saat ini wajib diisi untuk keamanan.</p><form id="af"><div class="formgrid"><div class="field full"><label>Email Baru</label><input type="email" name="email" value="<?=e($_SESSION['user_email']??'')?>" required></div><div class="field full"><label>Password Saat Ini</label><input type="password" name="current_password" autocomplete="current-password" required></div><div class="field"><label>Password Baru</label><input type="password" name="new_password" minlength="8" autocomplete="new-password" placeholder="Kosongkan jika hanya ganti email"></div><div class="field"><label>Konfirmasi Password Baru</label><input type="password" name="confirm_password" minlength="8" autocomplete="new-password"></div><div class="field full"><div class="secure">🔒 Password disimpan menggunakan hashing. Jangan gunakan password yang sama dengan akun penting lainnya.</div></div><button class="btn primary full">Simpan Perubahan</button></div></form>`;document.getElementById('af').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));f.action='update_account';req(f).then(x=>{if(x.ok){alert(x.message);location.reload()}else alert(x.message)})}}function productModal(p=null){p=p||{id:0,name:'',category_id:<?=($cats[0]['id']??0)?>,price:0,stock:0,image:'🍰',description:''};B.innerHTML=`<div class="modalhead"><h2>${p.id?'Edit Kue':'Tambah Kue'}</h2><button class="x" onclick="closeM()">×</button></div><form id="pf"><input type="hidden" name="id" value="${p.id}"><div class="formgrid"><div class="field"><label>Nama Kue</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>Kategori</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Harga Jual</label><div class="moneyinput"><span>Rp</span><input type="text" name="price_display" id="priceDisplay" inputmode="numeric" autocomplete="off" placeholder="0" required><input type="hidden" name="price" id="priceValue"></div><small class="notice">Contoh: 85.000</small></div><div class="field"><label>Stok Tersedia</label><input type="number" name="stock" min="0" step="1" value="${p.stock}" required><small class="notice">Jumlah unit kue yang siap dijual.</small></div><div class="field full"><label>Foto Kue</label><input type="file" id="imageFile" name="image_file" accept="image/jpeg,image/png,image/webp,image/gif"><small class="notice">Foto tidak akan dipotong otomatis. Setelah memilih foto, rapikan sendiri dengan geser dan zoom. Hasil disimpan HD.</small><div class="uploadPreview" id="uploadPreview"><img id="uploadPreviewImg" alt="Preview foto kue"></div><div class="uploadMeta" id="uploadMeta">Foto akan disimpan sesuai rasio asli. Tidak dipotong, tidak dipaksa memenuhi kotak.</div></div><div class="field full"><label>Emoji/Icon (opsional)</label><input name="image" maxlength="20" value="${esc(p.image?.startsWith('uploads/products/')?'🍰':(p.image||'🍰'))}"></div><div class="field full"><label>Deskripsi</label><textarea name="description">${esc(p.description||'')}</textarea></div><button type="submit" class="btn primary full">Simpan Kue</button></div></form>`;B.querySelector('[name=category_id]').value=p.category_id;M.classList.add('show');const pd=document.getElementById('priceDisplay'),pv=document.getElementById('priceValue');function syncPrice(){const n=String(pd.value||'').replace(/\D/g,'');pv.value=n;pd.value=n?Number(n).toLocaleString('id-ID'):''}pd.value=p.price?Number(p.price).toLocaleString('id-ID'):'';pv.value=p.price||0;pd.addEventListener('input',syncPrice);document.getElementById('pf').onsubmit=async e=>{e.preventDefault();syncPrice();let f=new FormData(e.target);f.set('action','save_product');const btn=e.target.querySelector('button[type=submit]');if(btn){btn.disabled=true;btn.textContent='Menyiapkan foto...'}await prepareImageForUpload(f);if(btn)btn.textContent='Menyimpan...';req(f).then(x=>{if(x.ok){closeM();location.reload()}else{if(btn){btn.disabled=false;btn.textContent='Simpan Kue'}alert(x.message)}})};initProductCrop()}function archive(id){if(confirm('Nonaktifkan kue ini?'))req({action:'archive_product',id}).then(go)}function checkout(){
 const subtotal=<?=json_encode($subtotal)?>;
 let payState={subtotal:Number(subtotal)||0,total:Number(subtotal)||0,discount:0,payment:'Cash'};
 M.classList.add('show');
 B.innerHTML=`<div class="modalhead"><h2>Pembayaran</h2><button type="button" class="x" id="closePay">×</button></div>
 <p class="notice">Masukkan uang yang diterima. Sistem menghitung kembalian secara otomatis.</p>
 <form id="cf" autocomplete="off">
  <div class="formgrid">
   <div class="field"><label>Nama Pelanggan</label><input name="name" placeholder="Pelanggan"></div>
   <div class="field"><label>No. HP</label><input name="phone" inputmode="tel" placeholder="08xxxxxxxxxx"></div>
   <div class="field full"><label>Catatan Pesanan</label><textarea name="notes" placeholder="Contoh: tulis ucapan, tanpa lilin, pickup jam 15.00"></textarea></div>
   <div class="field full"><label>Kupon</label><div class="coupon"><input name="coupon" id="coupon" placeholder="WELCOME20"><button type="button" class="btn secondary" id="couponBtn">Pakai</button></div><small id="couponMsg" class="notice"></small></div>
   <div class="field full"><label>Metode Pembayaran</label><div class="payrow" id="payMethods"><button type="button" class="pay active" data-p="Cash">Cash</button><button type="button" class="pay" data-p="QRIS">QRIS</button><button type="button" class="pay" data-p="Transfer">Transfer</button><button type="button" class="pay" data-p="Komplimen">Komplimen</button><button type="button" class="pay" data-p="Deposit">Deposit</button><button type="button" class="pay" data-p="NonTunai">Non Tunai</button></div><input type="hidden" name="payment" id="payment" value="Cash"><input type="hidden" name="payment_breakdown" id="paymentBreakdown"></div>
   <div class="field full"><button type="button" class="btn secondary" id="splitBtn">⇄ Pisah Bayar</button><div id="splitBox" style="display:none;margin-top:10px;padding:12px;background:#f8f4ef;border-radius:12px"><div class="notice">Bagi total ke dua metode pembayaran.</div><div class="formgrid" style="margin-top:8px"><select id="splitM1"><option>Cash</option><option>QRIS</option><option>Transfer</option><option>Deposit</option></select><input id="splitA1" class="moneyFormat" inputmode="numeric" placeholder="Nominal metode 1"><select id="splitM2"><option>QRIS</option><option>Cash</option><option>Transfer</option><option>Deposit</option></select><input id="splitA2" class="moneyFormat" inputmode="numeric" placeholder="Nominal metode 2"></div><small id="splitMsg" class="notice"></small></div></div>
   <div class="field full" id="cashBox"><label>Uang Diterima</label>
    <div class="quick"><button type="button" class="btn secondary quickCash" data-cash="total">Uang Pas</button><button type="button" class="btn secondary quickCash" data-cash="50000">Rp 50.000</button><button type="button" class="btn secondary quickCash" data-cash="100000">Rp 100.000</button><button type="button" class="btn secondary quickCash" data-cash="200000">Rp 200.000</button></div>
    <div class="moneyinput" style="margin-top:8px"><span>Rp</span><input type="text" name="cash" id="cash" inputmode="numeric" autocomplete="off" placeholder="0" aria-label="Uang diterima"></div>
    <div id="change" class="paymentResult" aria-live="polite">Masukkan uang diterima untuk melihat kembalian.</div>
   </div>
   <div class="field full"><div class="paytotal"><span>Total yang harus dibayar</span><b id="payTotal">Rp ${payState.total.toLocaleString('id-ID')}</b></div></div>
   <div class="field full"><div class="secure">🔒 Tidak menyimpan nomor kartu, CVV, PIN, atau password bank.</div></div>
   <button id="paySubmit" type="submit" class="btn primary full">Konfirmasi Pembayaran · Rp ${payState.total.toLocaleString('id-ID')}</button>
  </div>
 </form>`;
 const form=document.getElementById('cf'), cashEl=document.getElementById('cash'), changeEl=document.getElementById('change'), totalEl=document.getElementById('payTotal'), submitBtn=document.getElementById('paySubmit'), cashBox=document.getElementById('cashBox');
 const formatMoney=n=>Number(n||0).toLocaleString('id-ID');
 const numeric=v=>Number(String(v??'').replace(/\D/g,''))||0;
 function renderPayment(){
   totalEl.textContent='Rp '+formatMoney(payState.total);
   submitBtn.textContent='Konfirmasi Pembayaran · Rp '+formatMoney(payState.total);
   if(payState.payment==='Cash'){
     const received=numeric(cashEl.value);
     if(received<=0){changeEl.textContent='Masukkan uang diterima untuk melihat kembalian.';changeEl.className='paymentResult';}
     else if(received<payState.total){changeEl.textContent='Kurang: Rp '+formatMoney(payState.total-received);changeEl.className='paymentResult kurang';}
     else{changeEl.textContent='Kembalian: Rp '+formatMoney(received-payState.total);changeEl.className='paymentResult kembali';}
   }else{changeEl.textContent='Metode '+payState.payment+' dipilih. Tidak perlu uang tunai.';changeEl.className='paymentResult';}
 }
 function setCash(value){cashEl.value=value>0?formatMoney(value):'';cashEl.focus();renderPayment();}
 cashEl.addEventListener('input',()=>{const n=numeric(cashEl.value);cashEl.value=n?formatMoney(n):'';renderPayment();});
 cashEl.addEventListener('focus',()=>{cashEl.select();});
 document.querySelectorAll('#payMethods .pay').forEach(btn=>btn.addEventListener('click',()=>{
   document.querySelectorAll('#payMethods .pay').forEach(x=>x.classList.remove('active'));btn.classList.add('active');
   payState.payment=btn.dataset.p;document.getElementById('payment').value=payState.payment;
   cashBox.style.display=payState.payment==='Cash'?'block':'none';renderPayment();
 }));
 document.querySelectorAll('.quickCash').forEach(btn=>btn.addEventListener('click',()=>setCash(btn.dataset.cash==='total'?payState.total:Number(btn.dataset.cash))));
 document.getElementById('couponBtn').addEventListener('click',()=>{
   const code=document.getElementById('coupon').value.trim(),msg=document.getElementById('couponMsg');
   if(!code){payState.discount=0;payState.total=payState.subtotal;msg.textContent='Kupon dikosongkan.';renderPayment();return;}
   msg.textContent='Memeriksa kupon...';
   req({action:'coupon',code,subtotal:payState.subtotal}).then(x=>{
     if(x.ok){payState.discount=Math.min(payState.subtotal,Number(x.discount)||0);payState.total=Math.max(0,payState.subtotal-payState.discount);msg.textContent='✓ Diskon Rp '+formatMoney(payState.discount);setCash(payState.total);}
     else{payState.discount=0;payState.total=payState.subtotal;msg.textContent=x.message||'Kupon tidak berlaku.';renderPayment();}
   });
 });
 document.getElementById('closePay').addEventListener('click',closeM);
 const splitBtn=document.getElementById('splitBtn'),splitBox=document.getElementById('splitBox'),splitM1=document.getElementById('splitM1'),splitM2=document.getElementById('splitM2'),splitA1=document.getElementById('splitA1'),splitA2=document.getElementById('splitA2'),splitMsg=document.getElementById('splitMsg'),breakdown=document.getElementById('paymentBreakdown'); const formatMoneyInput=n=>{const d=String(n??'').replace(/\D/g,'');return d?Number(d).toLocaleString('id-ID'):''};document.querySelectorAll('.moneyFormat').forEach(el=>el.addEventListener('input',()=>el.value=formatMoneyInput(el.value)));
 splitBtn.addEventListener('click',()=>{splitBox.style.display=splitBox.style.display==='none'?'block':'none';});
 function nsplit(v){return Number(String(v||'').replace(/\D/g,''))||0}
 function updateSplit(){const a=nsplit(splitA1.value),b=nsplit(splitA2.value),sum=a+b;splitMsg.textContent='Total pisah: Rp '+formatMoney(sum)+' / Rp '+formatMoney(payState.total);breakdown.value=(a>0?splitM1.value+':'+a:'')+(a>0&&b>0?'|':'')+(b>0?splitM2.value+':'+b:'');}
 [splitA1,splitA2,splitM1,splitM2].forEach(x=>x.addEventListener('input',updateSplit));
 form.addEventListener('submit',e=>{
   e.preventDefault();
   if(splitBox.style.display!=='none'){updateSplit();if(nsplit(splitA1.value)+nsplit(splitA2.value)!==payState.total){alert('Nominal Pisah Bayar harus sama dengan total.');return;}} else {breakdown.value='';} if(payState.payment==='Cash' && numeric(cashEl.value)<payState.total){renderPayment();alert('Uang diterima masih kurang Rp '+formatMoney(payState.total-numeric(cashEl.value)));cashEl.focus();return;}
   submitBtn.disabled=true;submitBtn.textContent='Memproses pembayaran...';
   const f=Object.fromEntries(new FormData(form));f.action='checkout';f.cash=numeric(f.cash);
   req(f).then(x=>{
     if(!x.ok){submitBtn.disabled=false;renderPayment();alert(x.message);return;}
     B.innerHTML=`<div style="text-align:center;padding:18px"><div style="font-size:65px">🎉</div><h2>Pembayaran Berhasil</h2><p class="notice">Invoice ${esc(x.invoice)}</p><div class="row"><span>Total</span><b>Rp ${formatMoney(x.total)}</b></div><div class="row"><span>Kembalian</span><b>Rp ${formatMoney(x.change)}</b></div><p class="notice">Ref: ${esc(x.reference)}</p><button type="button" class="btn primary wide" onclick="location.reload()">Transaksi Baru</button><button type="button" class="btn secondary wide" onclick="window.print()">Cetak Bukti</button></div>`;
   });
 });
 setCash(payState.total);renderPayment();
}
function prepareImageForUpload(form){return new Promise(resolve=>{const file=document.getElementById('imageFile')?.files?.[0];if(!file){resolve();return}const img=new Image();const rd=new FileReader();rd.onload=()=>{img.onload=()=>{const max=2400,scale=Math.min(max/img.naturalWidth,max/img.naturalHeight,1);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,0,0,c.width,c.height);c.toBlob(blob=>{if(blob&&blob.size<4*1024*1024){form.delete('image_file');form.append('image_file',blob,'lushcake_hd_'+Date.now()+'.jpg')}resolve()},'image/jpeg',0.94)};img.src=rd.result};rd.readAsDataURL(file)})}function initProductCrop(){const file=document.getElementById('imageFile'),area=document.getElementById('uploadPreview'),img=document.getElementById('uploadPreviewImg'),meta=document.getElementById('uploadMeta');if(!file)return;file.onchange=()=>{const f=file.files?.[0];if(!f)return;if(f.size>12*1024*1024){alert('Ukuran gambar maksimal 12 MB.');file.value='';area.classList.remove('show');return}if(!/^image\/(jpeg|png|webp|gif)$/.test(f.type)){alert('Format gambar harus JPG, PNG, WEBP, atau GIF.');file.value='';area.classList.remove('show');return}const rd=new FileReader();rd.onload=()=>{img.src=rd.result;area.classList.add('show');meta.textContent='Preview utuh • '+(f.name||'foto')+' • '+Math.round(f.size/1024)+' KB'};rd.readAsDataURL(f)}}M.addEventListener('click',e=>{if(e.target===M)closeM()});</script></body></html>
